def compute(vars):
    stock_price = vars["Stock Price"]
    shares_outstanding = vars["Shares Outstanding"]

    market_capitalization = stock_price * shares_outstanding

    return {
        "value": market_capitalization,
        "trace": {
            "Stock Price": stock_price,
            "Shares Outstanding": shares_outstanding,
            "output_meta": {
                "currency": "USD",
                "scale": None,
                "unit": "USD"
            }
        }
    }
```
